SELECT '1. change_order_dates 含檢查段' AS 項目, (SELECT position('ORDER_MODULE_GUARD_V1' IN p.prosrc) > 0 FROM pg_proc p WHERE p.oid = to_regprocedure('public.change_order_dates(uuid, date, date, text, text, text)')) AS 結果
UNION ALL SELECT '2. change_order_dates 去掉檢查段後指紋等於套用前', (SELECT md5(replace(replace(p.prosrc, E'\r', ''), E'  -- ORDER_MODULE_GUARD_V1：已登入者需對該訂單館別的「訂單」模組 editable；service role（auth.uid() 為 null）照常通過\n  IF auth.uid() IS NOT NULL AND NOT public.staff_can_edit_module((SELECT o.accommodation_id FROM public.orders o WHERE o.id = _order_id), ''orders'') THEN\n    RAISE EXCEPTION ''權限不足：您對此訂單館別的「訂單」模組沒有編輯權限'' USING ERRCODE = ''42501'';\n  END IF;\n', '')) = 'c929d74bdf8f6fa763c1e29f76eeb70f' FROM pg_proc p WHERE p.oid = to_regprocedure('public.change_order_dates(uuid, date, date, text, text, text)'))
UNION ALL SELECT '3. change_order_dates 檢查段緊接在第一個 BEGIN 之後', (SELECT position(E'\nBEGIN\n' || E'  -- ORDER_MODULE_GUARD_V1：已登入者需對該訂單館別的「訂單」模組 editable；service role（auth.uid() 為 null）照常通過\n  IF auth.uid() IS NOT NULL AND NOT public.staff_can_edit_module((SELECT o.accommodation_id FROM public.orders o WHERE o.id = _order_id), ''orders'') THEN\n    RAISE EXCEPTION ''權限不足：您對此訂單館別的「訂單」模組沒有編輯權限'' USING ERRCODE = ''42501'';\n  END IF;\n' IN replace(p.prosrc, E'\r', '')) > 0 FROM pg_proc p WHERE p.oid = to_regprocedure('public.change_order_dates(uuid, date, date, text, text, text)'))
UNION ALL SELECT '4. change_order_dates 仍為 SECURITY DEFINER；anon 不可、authenticated／service_role 可執行', (SELECT p.prosecdef FROM pg_proc p WHERE p.oid = to_regprocedure('public.change_order_dates(uuid, date, date, text, text, text)')) AND NOT has_function_privilege('anon', to_regprocedure('public.change_order_dates(uuid, date, date, text, text, text)'), 'EXECUTE') AND has_function_privilege('authenticated', to_regprocedure('public.change_order_dates(uuid, date, date, text, text, text)'), 'EXECUTE') AND has_function_privilege('service_role', to_regprocedure('public.change_order_dates(uuid, date, date, text, text, text)'), 'EXECUTE')
UNION ALL SELECT '5. sync_order_rooms_v1：anon 不可、authenticated／service_role 可、授權清單無 PUBLIC', NOT has_function_privilege('anon', to_regprocedure('public.sync_order_rooms_v1(uuid, timestamp with time zone, jsonb)'), 'EXECUTE') AND has_function_privilege('authenticated', to_regprocedure('public.sync_order_rooms_v1(uuid, timestamp with time zone, jsonb)'), 'EXECUTE') AND has_function_privilege('service_role', to_regprocedure('public.sync_order_rooms_v1(uuid, timestamp with time zone, jsonb)'), 'EXECUTE') AND (SELECT p.proacl IS NOT NULL AND NOT EXISTS (SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee = 0) FROM pg_proc p WHERE p.oid = to_regprocedure('public.sync_order_rooms_v1(uuid, timestamp with time zone, jsonb)'))
UNION ALL SELECT '6. clear_order_room_pricing_template：anon 不可、authenticated／service_role 可、授權清單無 PUBLIC', NOT has_function_privilege('anon', to_regprocedure('public.clear_order_room_pricing_template(uuid)'), 'EXECUTE') AND has_function_privilege('authenticated', to_regprocedure('public.clear_order_room_pricing_template(uuid)'), 'EXECUTE') AND has_function_privilege('service_role', to_regprocedure('public.clear_order_room_pricing_template(uuid)'), 'EXECUTE') AND (SELECT p.proacl IS NOT NULL AND NOT EXISTS (SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee = 0) FROM pg_proc p WHERE p.oid = to_regprocedure('public.clear_order_room_pricing_template(uuid)'))
UNION ALL SELECT '7. 除 change_order_dates 外 9 支函式指紋未變', (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('change_order_dates', 'admin_delete_order', 'attach_trip_products_to_recent_order', 'clear_order_room_pricing_template', 'sync_order_rooms_v1', 'update_order_fields_v1', 'update_paid_order_addons_v3', 'update_paid_order_discount_v2', 'staff_can_edit_module', 'get_staff_module_permission') AND p.proname <> 'change_order_dates' AND md5(replace(p.prosrc, E'\r', '')) = CASE p.proname WHEN 'change_order_dates' THEN 'c929d74bdf8f6fa763c1e29f76eeb70f' WHEN 'admin_delete_order' THEN 'c475f3c838693c49de1c884c68f59e2e' WHEN 'attach_trip_products_to_recent_order' THEN '22f24eea56e8a00a55bcb0f034691222' WHEN 'clear_order_room_pricing_template' THEN '3e2a820ae3b78d49f689f270bbc68cd2' WHEN 'sync_order_rooms_v1' THEN '957646923f7e28e9fe7c75b50ed26643' WHEN 'update_order_fields_v1' THEN '281dd4b043ecf7204d331c1419be446b' WHEN 'update_paid_order_addons_v3' THEN '6f33325215f67094a7e5992c02ef9943' WHEN 'update_paid_order_discount_v2' THEN '072ae35e8cbadaf141d3ee5cc5ff0d3f' WHEN 'staff_can_edit_module' THEN '2bc9cdfb8f98b1ea26c361f9dca1c095' WHEN 'get_staff_module_permission' THEN 'aea42e17d7f8d452d1d241286e70dcb8' END) = 9;

SELECT p.oid::regprocedure::text AS 函式, COALESCE(p.proacl::text, '(NULL)') AS 套用後授權, md5(replace(p.prosrc, E'\r', '')) AS 指紋
FROM pg_proc p
WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('change_order_dates', 'admin_delete_order', 'attach_trip_products_to_recent_order', 'clear_order_room_pricing_template', 'sync_order_rooms_v1', 'update_order_fields_v1', 'update_paid_order_addons_v3', 'update_paid_order_discount_v2', 'staff_can_edit_module', 'get_staff_module_permission')
ORDER BY 1;
